INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Supporting organization responsiveness test under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'The Davis Family Foundation, currently a private foundation, wants to restructure as a supporting organization under Section 509(a)(3) to avoid private foundation excise taxes. The foundation plans to support a single public charity hospital but intends to retain full control over investment decisions, grant timing, and program selection without meaningful involvement from the hospital''s board. Evaluate whether this restructuring would achieve the desired reclassification.', '["The restructuring will likely fail because a Type III supporting organization must demonstrate responsiveness to the supported organization, and retaining full control without the hospital''s meaningful involvement undermines this requirement", "The restructuring will succeed because any organization that designates a public charity as its supported organization automatically qualifies under Section 509(a)(3)", "The restructuring will succeed because Section 509(a)(3) only requires naming the supported charity in governing documents", "The restructuring will fail solely because private foundations are permanently barred from converting to any other classification"]'::jsonb, 0, 'Under Section 509(a)(3), a supporting organization must be organized and operated exclusively to support one or more public charities. Type III supporting organizations must satisfy a responsiveness test demonstrating meaningful connection to the supported organization. Retaining full operational control without the hospital''s involvement fails this test. Unlike choice B, automatic qualification is not available — the organization must meet operational requirements beyond simply designating a supported charity.', 'hard', 4),

-- Q2: medium / L2 — Form 990-PF mandatory for all private foundations
(3, 'Tax-Exempt Organizations', 'The Greenleaf Foundation, a private foundation with gross receipts of $35,000 and total assets of $150,000, asks its tax advisor which annual information return it must file with the IRS. Which form is required?', '["Form 990-N (e-Postcard) because gross receipts are below $50,000", "Form 990-PF because all private foundations must file this form regardless of size", "Form 990-EZ because gross receipts are under $200,000 and assets are under $500,000", "No filing is required because both gross receipts and total assets are below minimum thresholds"]'::jsonb, 1, 'Under IRC Section 6033, all private foundations must file Form 990-PF regardless of gross receipts or total assets. The size-based thresholds for Form 990, 990-EZ, and 990-N apply only to public charities and other exempt organizations — not private foundations. Unlike choice A, the e-Postcard option is not available to private foundations even when gross receipts fall below $50,000.', 'medium', 2),

-- Q3: medium / L2 — Section 501(h) expenditure test election
(3, 'Tax-Exempt Organizations', 'Hope Alliance, a 501(c)(3) public charity, elects under Section 501(h) to use the expenditure test for measuring its lobbying activities. Its exempt purpose expenditures total $600,000 for the year. What is the primary benefit of this election?', '["It eliminates the prohibition on political campaign activity for the electing organization", "It allows unlimited lobbying expenditures as long as they are properly documented", "The election replaces the vague ''substantial part'' test with specific dollar thresholds that provide a clear safe harbor for permissible lobbying", "It converts lobbying expenses into deductible charitable contributions for donors"]'::jsonb, 2, 'Under Section 501(h), eligible public charities may elect the expenditure test, which replaces the subjective "substantial part" standard with defined dollar limits based on exempt purpose expenditures. This provides a measurable safe harbor so organizations know exactly how much lobbying is permissible. Unlike choice A, the election has no effect on the absolute prohibition against political campaign activity, which remains in force regardless of any election.', 'medium', 2),

-- Q4: medium / L2 — Controlled entity rent payments and UBIT
(3, 'Tax-Exempt Organizations', 'Bright Future Charity, a 501(c)(3), owns 90% of the voting stock in Bright Services, Inc., a taxable corporation. Bright Services pays $200,000 in annual rent to the charity for office space. Independent appraisals establish fair market rent at $120,000. How is the $200,000 rent payment treated for UBIT purposes?', '["The entire $200,000 is excluded from UBIT because rents from real property are always excluded", "Only the $120,000 fair market value portion is excluded and the remaining $80,000 is exempt function revenue", "The entire $200,000 is subject to UBIT because any payment from a controlled entity is fully taxable", "The $80,000 excess over fair market value is treated as unrelated business income under the controlled entity rules"]'::jsonb, 3, 'Under IRC Section 512(b)(13), when a tax-exempt organization receives rent from a controlled subsidiary (80% or more ownership), the amount exceeding fair market value is treated as UBIT. The $80,000 excess ($200,000 minus $120,000 FMV) is unrelated business income. Unlike choice C, only the portion exceeding fair market value is included in UBIT — the FMV portion retains the normal real property rent exclusion.', 'medium', 2),

-- Q5: hard / L4 — Private benefit vs private inurement distinction
(3, 'Tax-Exempt Organizations', 'Riverside Education Fund, a 501(c)(3), contracts with an unrelated for-profit company to develop its online curriculum. The contract provides the company with compensation significantly above market rates, but no officers, directors, or insiders of the charity have any financial interest in the company. The IRS examines the arrangement. Analyze how the private benefit doctrine and the private inurement prohibition apply to this transaction.', '["Private benefit applies because it covers excessive benefits to any person — insider or outsider — while private inurement applies only to insiders; here, private benefit is the relevant concern since the company is an outsider", "Private inurement applies because any above-market payment violates the inurement prohibition regardless of the recipient''s relationship to the organization", "Neither doctrine applies because the company is providing legitimate services that further the charity''s exempt purpose", "Both doctrines are identical in scope and apply equally to insiders and outsiders without distinction"]'::jsonb, 0, 'Under Section 501(c)(3), the private benefit doctrine prohibits more than incidental benefits to any private party, whether or not they are insiders. The private inurement prohibition specifically targets benefits flowing to insiders with substantial influence. Here, the above-market payment to an unrelated company triggers private benefit analysis. Unlike choice B, private inurement requires an insider relationship that does not exist in this scenario.', 'hard', 4),

-- Q6: easy / L1 — Dissolution clause requirement for 501(c)(3)
(3, 'Tax-Exempt Organizations', 'What must a 501(c)(3) organization''s governing documents include regarding asset distribution upon dissolution?', '["A provision allowing assets to be distributed to the founder''s family members", "A clause permitting assets to be divided equally among current employees", "A requirement that assets be returned to original donors on a pro-rata basis", "A provision that assets will be distributed to another exempt organization or to the government"]'::jsonb, 3, 'Under Section 501(c)(3), the organizational test requires governing documents to include a dissolution clause providing that upon dissolution, remaining assets will be distributed to another tax-exempt organization or to the government. This prevents private individuals from benefiting when the organization ceases operations. Unlike choice C, there is no requirement to return assets to donors — they must go to another exempt purpose.', 'easy', 1),

-- Q7: medium / L3 — Bingo game exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Valley Community Church, a 501(c)(3), operates weekly bingo games open to the public using paid employees. The church earns $45,000 annually from bingo. No commercial bingo operations exist in the jurisdiction. A competing entertainment venue argues the income should be subject to UBIT. Apply the bingo exclusion to determine the correct tax treatment.', '["Subject to UBIT because paid employees run the games rather than volunteers", "Excluded from UBIT because the games are legal bingo conducted in a jurisdiction where commercial bingo is not ordinarily carried on", "Excluded only if total bingo revenue stays below $50,000 annually", "Subject to UBIT because weekly operation satisfies the ''regularly carried on'' requirement"]'::jsonb, 1, 'Under Section 513(f), bingo games are excluded from UBIT when they are legal and conducted in a jurisdiction where commercial bingo is not ordinarily carried on. Unlike the volunteer labor exclusion, the bingo exclusion does not require volunteer staffing — it focuses on whether commercial bingo exists in the jurisdiction. Choice A incorrectly applies the volunteer labor exclusion standard to the separate bingo game exclusion.', 'medium', 3),

-- Q8: hard / L4 — Expenditure responsibility for grants to non-charities under Section 4945
(3, 'Tax-Exempt Organizations', 'The Carlton Private Foundation wants to make a $500,000 grant to a 501(c)(4) social welfare organization to fund community health programs. The foundation''s board approves the grant but does not implement expenditure responsibility procedures, reasoning that the recipient is already tax-exempt. Evaluate the tax consequences under Section 4945.', '["No taxable expenditure occurs because all Section 501(c) organizations are treated identically for grant purposes", "The grant is automatically prohibited because private foundations cannot make grants to any organization other than a 501(c)(3)", "The grant is a taxable expenditure because grants to non-501(c)(3) organizations require expenditure responsibility, and failure to exercise it triggers a 20% initial excise tax on the $500,000", "The grant is permissible without expenditure responsibility because 501(c)(4) organizations share the same charitable purpose as 501(c)(3) organizations"]'::jsonb, 2, 'Under Section 4945(d)(4), grants by a private foundation to organizations other than 501(c)(3) public charities are taxable expenditures unless the foundation exercises expenditure responsibility. A 501(c)(4) is not a 501(c)(3), so expenditure responsibility is required. Failure results in a 20% initial excise tax. Unlike choice B, grants to non-charities are permitted but only with proper expenditure responsibility procedures in place.', 'hard', 4),

-- Q9: easy / L2 — Form 990-N e-Postcard eligibility threshold
(3, 'Tax-Exempt Organizations', 'Little Creek Animal Rescue, a 501(c)(3) public charity, has gross receipts of $38,000 and total assets of $90,000 for the current tax year. Which annual information return should this organization file?', '["Form 990 because all 501(c)(3) organizations must file the full return", "Form 990-PF because the organization''s assets exceed $50,000", "Form 990-EZ because gross receipts exceed $25,000", "Form 990-N (e-Postcard) because gross receipts are normally $50,000 or less"]'::jsonb, 3, 'Under IRC Section 6033(i), tax-exempt organizations with gross receipts normally $50,000 or less may file Form 990-N (e-Postcard), an electronic notice requiring only basic information such as name, address, and EIN. Little Creek''s $38,000 gross receipts fall below this threshold. Unlike choice C, Form 990-EZ applies to organizations with gross receipts between $50,000 and $200,000, not those below the e-Postcard threshold.', 'easy', 2),

-- Q10: hard / L3 — Personal property rents and the 10% incidental threshold
(3, 'Tax-Exempt Organizations', 'Heritage Arts Council, a 501(c)(3), leases a building to a commercial tenant. The lease includes office furniture and equipment. Annual rents total $100,000, of which $8,000 is attributable to the personal property (furniture and equipment) and $92,000 to the real property. Apply the UBIT rules for mixed real and personal property rents to determine the tax treatment.', '["The entire $100,000 is subject to UBIT because the lease includes personal property", "The $8,000 personal property portion is subject to UBIT while the $92,000 real property portion is excluded", "Only the $92,000 real property rent is excluded; the $8,000 must be reported separately as unrelated business income", "The entire $100,000 is excluded from UBIT because the personal property rent is incidental at 8%, which is below the 10% threshold"]'::jsonb, 3, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT. When a lease includes both real and personal property, the personal property portion is also excluded if it is incidental — defined as less than 10% of total rents under the lease. Here, $8,000 is 8% of $100,000, falling below the 10% threshold, so the entire amount is excluded. Unlike choice B, separate taxation of the personal property rent is not required when it falls below 10%.', 'hard', 3),

-- Q11: medium / L3 — Convenience exclusion for hospital cafeteria
(3, 'Tax-Exempt Organizations', 'Lakeside University Hospital, a 501(c)(3), operates a cafeteria on its premises that serves meals primarily to patients, their visiting families, and hospital employees during shift hours. The cafeteria also occasionally serves walk-in visitors from the neighborhood. Apply the UBIT convenience exclusion to determine the tax treatment of this income.', '["The cafeteria income qualifies for the convenience exclusion because the activity is conducted primarily for the convenience of patients and employees, even though some walk-in visitors are served", "The cafeteria income is fully subject to UBIT because any service to outsiders disqualifies the convenience exclusion entirely", "The cafeteria income is excluded solely because hospitals are exempt from UBIT on all activities", "The cafeteria income is subject to UBIT because selling prepared food is always an unrelated trade or business"]'::jsonb, 0, 'Under Section 513(a)(2), activities conducted primarily for the convenience of members, students, patients, officers, or employees are excluded from UBIT. The hospital cafeteria primarily serves patients and employees, satisfying the exclusion despite some incidental service to walk-in visitors. Unlike choice B, occasional service to outsiders does not disqualify the exclusion when the activity primarily serves the specified groups.', 'medium', 3),

-- Q12: easy / L1 — Form 990-EZ filing thresholds
(3, 'Tax-Exempt Organizations', 'What are the filing thresholds for an exempt organization to use Form 990-EZ instead of the full Form 990?', '["Gross receipts over $500,000 and total assets over $1,000,000", "Gross receipts under $200,000 and total assets under $500,000", "Gross receipts under $100,000 regardless of total assets", "Gross receipts under $50,000 and total assets under $250,000"]'::jsonb, 1, 'Under IRC Section 6033, a tax-exempt organization may file Form 990-EZ if gross receipts are less than $200,000 and total assets are less than $500,000. Organizations exceeding either threshold must file the full Form 990. Unlike choice D, the $50,000 gross receipts figure applies to Form 990-N (e-Postcard) eligibility, not Form 990-EZ.', 'easy', 1),

-- Q13: medium / L3 — NOL deduction rules for UBIT
(3, 'Tax-Exempt Organizations', 'Cornerstone Education Foundation, a 501(c)(3), had a $25,000 net operating loss from unrelated business activities in 2025. In 2026, it reports $60,000 in unrelated business income and $15,000 in net investment income. Apply the UBIT net operating loss rules to determine how the 2025 NOL may be used.', '["The $25,000 NOL offsets both the $60,000 UBI and the $15,000 investment income, reducing total taxable income to $50,000", "No NOL deduction is available because tax-exempt organizations cannot carry forward business losses", "The $25,000 NOL may offset only the $60,000 in unrelated business income, reducing UBTI to $35,000 before the specific deduction — it cannot offset investment income", "The $25,000 NOL may be used only if the foundation elects to carry it forward instead of carrying it back to prior years"]'::jsonb, 2, 'Under Section 512(b)(6), the net operating loss deduction for UBIT is computed using only unrelated business income items. The NOL can offset future UBI but cannot reduce investment income or other exempt function revenue. Here, the $25,000 NOL reduces UBI from $60,000 to $35,000. Unlike choice A, investment income is excluded from UBIT calculations and is not available for NOL offset.', 'medium', 3),

-- Q14: easy / L1 — Form 990 filing deadline for calendar-year organizations
(3, 'Tax-Exempt Organizations', 'When is the annual Form 990 filing deadline for a calendar-year tax-exempt organization?', '["May 15", "April 15", "March 15", "June 15"]'::jsonb, 0, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the end of the organization''s tax year. For calendar-year organizations (year ending December 31), this deadline is May 15. Extensions of up to six months are available using Form 8868. Unlike choice B, the April 15 deadline applies to individual income tax returns, not exempt organization information returns.', 'easy', 1),

-- Q15: medium / L2 — Research exclusion from UBIT for non-university organizations
(3, 'Tax-Exempt Organizations', 'Wildflower Conservation Trust, a 501(c)(3) environmental nonprofit (not a university or hospital), conducts proprietary soil analysis research under contract for a private timber company. The results are kept confidential and not made available to the public. Is this research income excluded from UBIT?', '["Excluded because all research conducted by 501(c)(3) organizations is exempt from UBIT regardless of circumstances", "Excluded because the research relates to the organization''s conservation mission", "Excluded because the research generates passive income similar to royalties", "Subject to UBIT because no research exclusion applies — the organization is not a university or hospital, the research is not for the government, and results are not publicly available"]'::jsonb, 3, 'Under Section 512(b)(7)-(9), research income is excluded from UBIT only for research performed for the government, research by a college, university, or hospital, or research whose results are freely available to the public. The Trust meets none of these exclusions — it is not a university or hospital, the client is private, and results are confidential. Unlike choice A, the research exclusion does not apply to all exempt organizations automatically.', 'medium', 2),

-- Q16: medium / L2 — Failure-to-file penalty calculation
(3, 'Tax-Exempt Organizations', 'Crossroads Community Center, a 501(c)(3) public charity with $180,000 in gross receipts, files its Form 990-EZ 45 days late without reasonable cause. Under IRS penalty provisions, what penalty applies?', '["No penalty because the organization filed Form 990-EZ rather than the full Form 990", "$900, calculated as $20 per day for each of the 45 late days, which is below the maximum penalty cap", "$9,000, representing 5% of gross receipts regardless of the number of days the return is late", "$45, calculated as $1 per day for each day the return is late"]'::jsonb, 1, 'Under IRC penalty provisions for organizations with gross receipts under $1,186,000, the failure-to-file penalty is $20 per day, up to the lesser of $10,500 or 5% of gross receipts. Here, $20 times 45 days equals $900. The cap is the lesser of $10,500 or $9,000 (5% of $180,000), so $9,000 is the maximum. Since $900 is below the cap, the penalty is $900. Unlike choice C, the penalty accrues daily rather than applying a flat percentage.', 'medium', 2),

-- Q17: medium / L2 — Organization manager tax under Section 4958 with $20,000 cap
(3, 'Tax-Exempt Organizations', 'Pinecrest Community Center, a 501(c)(3), pays its program director $280,000 per year. Comparable compensation at similar organizations is $180,000. A board member who knew the compensation was above market approved the arrangement. Under Section 4958, what excise tax applies to the board member?', '["No excise tax applies to board members because only the disqualified person is liable", "$20,000 because the per-transaction cap always applies regardless of the excess benefit amount", "$10,000, calculated as 10% of the $100,000 excess benefit, which is below the $20,000 per-transaction cap for organization managers", "$25,000, calculated as 25% of the excess benefit"]'::jsonb, 2, 'Under Section 4958, an organization manager who knowingly participates in an excess benefit transaction is subject to a 10% excise tax on the excess benefit, capped at $20,000 per transaction. The excess benefit is $100,000 ($280,000 minus $180,000 comparable compensation), so 10% equals $10,000. Since $10,000 is under the $20,000 cap, the full $10,000 applies. Unlike choice A, managers who knowingly participate face separate liability.', 'medium', 2),

-- Q18: easy / L1 — Additional tax on uncorrected excess benefit transactions (200%)
(3, 'Tax-Exempt Organizations', 'Under Section 4958, what additional excise tax is imposed on a disqualified person who fails to correct an excess benefit transaction within the taxable period?', '["25% of the excess benefit", "100% of the excess benefit", "50% of the excess benefit", "200% of the excess benefit"]'::jsonb, 3, 'Under Section 4958(b), if a disqualified person does not correct the excess benefit transaction within the taxable period, an additional excise tax of 200% of the excess benefit is imposed. This is on top of the initial 25% tax. The severe rate is designed to compel prompt correction. Unlike choice B, the additional tax is 200%, not 100% — reflecting Congress''s intent to ensure disqualified persons restore the benefit to the organization.', 'easy', 1),

-- Q19: easy / L1 — Form 8868 purpose (filing extension for exempt organizations)
(3, 'Tax-Exempt Organizations', 'What is the purpose of IRS Form 8868 for tax-exempt organizations?', '["To request an automatic extension of time to file Form 990 or other exempt organization returns", "To apply for initial tax-exempt status under Section 501(c)(3)", "To report unrelated business taxable income", "To elect the Section 501(h) expenditure test for lobbying"]'::jsonb, 0, 'Under IRC Section 6081, Form 8868 is used by tax-exempt organizations to request an automatic extension of up to six months to file their annual information returns (Form 990, 990-EZ, 990-PF, or 990-T). Unlike choice B, the application for tax-exempt status is filed on Form 1023 (or Form 1023-EZ), not Form 8868. Form 8868 only extends the filing deadline and does not change the organization''s tax obligations.', 'easy', 1),

-- Q20: medium / L2 — One-third public support test under Section 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Cedar Ridge Foundation, a 501(c)(3), normally receives 40% of its total support from government grants and broad-based public donations. The remaining 60% comes from investment income and a small number of large donors. The organization wants to avoid private foundation classification. Under Section 509(a)(1), does it qualify as a public charity?', '["No, because more than half of its support comes from non-public sources", "No, because receiving investment income disqualifies an organization from public charity status", "Yes, because receiving at least one-third of total support from government and public sources satisfies the Section 509(a)(1) public support test", "Yes, but only if the organization has been in existence for at least five years"]'::jsonb, 2, 'Under Section 509(a)(1), an organization qualifies as a public charity if it normally receives a substantial part of its support — at least one-third — from governmental sources and the general public. Cedar Ridge receives 40% from these sources, exceeding the one-third threshold. Unlike choice A, the test requires only one-third public support, not a majority — having more than 50% from non-public sources does not disqualify the organization.', 'medium', 2),

-- Q21: hard / L4 — Debt-financed income calculation with debt/basis ratio
(3, 'Tax-Exempt Organizations', 'Oakwood Community Center, a 501(c)(3), purchases a commercial building for $1,000,000, financing $600,000 with a mortgage. The building is rented to commercial tenants generating $150,000 in annual rental income with $40,000 in directly allocable expenses. Calculate the organization''s unrelated business taxable income from this debt-financed property, applying the debt/basis ratio and the $1,000 specific deduction.', '["$150,000, because all rental income from debt-financed property is fully taxable", "$90,000, because 60% of gross rental income is taxable with no proportional deduction for expenses", "$66,000, representing 60% of net income before the specific deduction", "$65,000, because 60% of both income ($90,000) and deductions ($24,000) yields $66,000 net, less the $1,000 specific deduction"]'::jsonb, 3, 'Under Section 514, debt-financed income is subject to UBIT in proportion to the average acquisition indebtedness divided by the average adjusted basis. The ratio is $600,000/$1,000,000 = 60%. Taxable income: $150,000 x 60% = $90,000. Deductions: $40,000 x 60% = $24,000. Net: $66,000 minus the $1,000 specific deduction = $65,000. Unlike choice B, deductions must also be proportioned by the debt/basis ratio.', 'hard', 4),

-- Q22: medium / L2 — Schedule A of Form 990 (public charity status)
(3, 'Tax-Exempt Organizations', 'Which Form 990 schedule requires a tax-exempt organization to report its public charity classification and public support calculations?', '["Schedule B — Schedule of Contributors", "Schedule A — Public Charity Status and Public Support", "Schedule J — Compensation Information for officers, directors, and key employees", "Schedule D — Supplemental Financial Statements"]'::jsonb, 1, 'Under IRC Section 6033, Schedule A of Form 990 is specifically designated for reporting an organization''s public charity status and computing its public support percentages under Section 509(a). This schedule demonstrates that the organization meets the support tests required to avoid private foundation classification. Unlike choice C, Schedule J addresses compensation information for officers and key employees, not public charity qualification.', 'medium', 2),

-- Q23: easy / L1 — Churches, hospitals, and schools as automatic public charities
(3, 'Tax-Exempt Organizations', 'Under Section 509(a)(1), which types of 501(c)(3) organizations are automatically classified as public charities without needing to meet the public support tests?', '["Only organizations with annual gross receipts exceeding $1,000,000", "Only organizations that have been in existence for more than 10 years", "Only organizations that receive no private donations", "Churches, schools, and hospitals"]'::jsonb, 3, 'Under Section 509(a)(1), churches, schools, and hospitals are automatically classified as public charities regardless of their funding sources or support test calculations. These organizations are recognized as inherently public due to their nature and broad community service. Unlike choice A, the automatic classification is based on the type of organization, not its financial size or revenue level.', 'easy', 1),

-- Q24: hard / L4 — Section 4945 taxable expenditure categories analysis
(3, 'Tax-Exempt Organizations', 'The Mitchell Family Foundation, a private foundation, engages in the following during 2026: (1) a $200,000 grant to a 501(c)(3) public charity for educational programs, (2) a $50,000 grant to a graduate student for research without prior IRS approval of the selection criteria, (3) $25,000 spent on lobbying state legislators, and (4) a $75,000 grant to a 501(c)(4) civic league with full expenditure responsibility procedures in place. Evaluate which activities are taxable expenditures under Section 4945.', '["Activities (2) and (3) are taxable expenditures — the individual grant lacks IRS-approved selection criteria, and lobbying is prohibited; activities (1) and (4) are permissible", "All four activities are taxable expenditures because private foundations may not make any grants", "Only activity (3) is a taxable expenditure; individual grants are always permissible for private foundations", "Activities (2), (3), and (4) are all taxable expenditures because any grant to a non-501(c)(3) organization is prohibited regardless of expenditure responsibility"]'::jsonb, 0, 'Under Section 4945, taxable expenditures include lobbying, grants to individuals without IRS-approved selection criteria, and grants to non-charities without expenditure responsibility. Activity (1) is permissible (grant to public charity). Activity (2) is a taxable expenditure (no IRS-approved criteria). Activity (3) is a taxable expenditure (lobbying). Activity (4) is permissible because expenditure responsibility was exercised. Unlike choice D, grants to non-501(c)(3) entities are allowed with proper expenditure responsibility.', 'hard', 4),

-- Q25: easy / L1 — Private foundation presumption (default classification)
(3, 'Tax-Exempt Organizations', 'Under Section 509, how is a newly recognized 501(c)(3) organization classified by default?', '["Public charity until it fails to meet the support test", "Private foundation unless it demonstrates it qualifies as a public charity", "Social welfare organization under Section 501(c)(4)", "Supporting organization under Section 509(a)(3)"]'::jsonb, 1, 'Under Section 509(a), all 501(c)(3) organizations are presumed to be private foundations unless they demonstrate they qualify as public charities under one of the exceptions in Section 509(a)(1) through (4). The burden is on the organization to prove public charity status. Unlike choice A, the default classification is private foundation, not public charity — organizations must affirmatively establish their public charity qualification.', 'easy', 1),

-- Q26: easy / L1 — Foundation manager tax on self-dealing under Section 4941
(3, 'Tax-Exempt Organizations', 'Under Section 4941, what excise tax rate applies to a foundation manager who knowingly participates in a self-dealing transaction?', '["10% of the amount involved", "25% of the amount involved", "5% of the amount involved", "20% of the amount involved"]'::jsonb, 2, 'Under Section 4941(a)(2), a foundation manager who knowingly participates in an act of self-dealing between a private foundation and a disqualified person is subject to a 5% excise tax on the amount involved. This is separate from the 10% initial tax imposed on the self-dealer. Unlike choice A, the 10% rate applies to the disqualified person who engaged in the transaction, not to the foundation manager.', 'easy', 1),

-- Q27: medium / L3 — Excess business holdings 35% exception with effective control
(3, 'Tax-Exempt Organizations', 'The Westfield Foundation, a private foundation, owns 15% of the voting stock in Apex Corporation. Disqualified persons own an additional 12%, for a combined holding of 27%. Independent third parties own the remaining 73% and exercise effective control over the corporation''s management. Apply the excess business holdings rules of Section 4943 to determine whether a violation exists.', '["No excess business holdings exist because the 35% permitted holding applies when effective control of the corporation rests with persons who are not disqualified persons", "The foundation has excess business holdings of 7% because the combined 27% exceeds the general 20% limit", "The foundation has excess business holdings of 15% because only the foundation''s direct holdings count under Section 4943", "No excess holdings exist because the 20% limit applies only to the foundation''s own holdings, not combined holdings with disqualified persons"]'::jsonb, 0, 'Under Section 4943, the general permitted holding is 20% combined between a foundation and disqualified persons. However, if effective control of the corporation rests with persons who are not disqualified persons, the permitted holding increases to 35%. Since independent parties own 73% and exercise effective control, the 35% limit applies. The combined 27% is below 35%, so no violation exists. Unlike choice B, the general 20% rule does not apply when the effective control exception is met.', 'medium', 3),

-- Q28: medium / L3 — Section 4942 initial tax and correction period
(3, 'Tax-Exempt Organizations', 'Harbor Foundation, a private foundation, has non-charitable-use assets valued at $8,000,000. It distributes $300,000 for charitable purposes during the year, falling short of the required minimum. Apply Section 4942 to determine the initial excise tax and the consequences of failing to correct the shortfall.', '["The initial excise tax is $30,000 (30% of the $100,000 undistributed amount), and failure to correct within the taxable period triggers an additional 100% tax on the remaining shortfall", "The initial excise tax is $10,000 (10% of the undistributed amount), consistent with the self-dealing tax rate", "No excise tax applies because the foundation made charitable distributions during the year", "The initial excise tax is $20,000 (20% of the undistributed amount), matching the taxable expenditure rate under Section 4945"]'::jsonb, 0, 'Under Section 4942, a private foundation must distribute at least 5% of non-charitable-use assets annually. The required distribution is $400,000 (5% of $8,000,000), creating a $100,000 shortfall. The initial excise tax is 30% of the undistributed amount ($30,000). If the foundation fails to correct the shortfall during the taxable period, a 100% additional tax applies. Unlike choice B, the 30% rate for undistributed income is distinct from the 10% self-dealing rate.', 'medium', 3),

-- Q29: medium / L3 — Personal property lease as UBIT (no real property exclusion)
(3, 'Tax-Exempt Organizations', 'Beacon Foundation, a 501(c)(3), leases construction equipment (personal property only, with no real property component) to a local contractor for $50,000 per year on an ongoing basis. The foundation''s treasurer believes rental income is always excluded from UBIT. Apply the UBIT rules to determine the correct treatment.', '["Excluded because all rental income received by tax-exempt organizations is automatically exempt from UBIT", "Subject to UBIT because the rental income exclusion applies only to rents from real property, and rents from a standalone personal property lease do not qualify for the exclusion", "Excluded because rental income is passive income that is always excluded from UBIT regardless of property type", "Subject to UBIT only if the annual rental amount exceeds $100,000"]'::jsonb, 1, 'Under IRC Section 512(b)(3), rents from real property are excluded from UBIT, but rents from personal property are not excluded when the personal property is leased separately. Equipment is personal property, and the lease contains no real property component, so the rental income is subject to UBIT. Unlike choice C, the passive income exclusion under Section 512(b)(1) covers dividends, interest, and royalties — not rents from personal property leased independently.', 'medium', 3),

-- Q30: medium / L3 — Operational test and "primarily" standard
(3, 'Tax-Exempt Organizations', 'Bright Horizons, a 501(c)(3) literacy organization, spends 45% of its total expenditures on literacy programs, 35% on operating a commercial printing business unrelated to its mission, and 20% on administrative costs. A board member asserts the organization satisfies the operational test because literacy programs remain its largest single activity. Apply the operational test to evaluate this claim.', '["The board member is correct because the largest single activity is exempt in nature", "The operational test is satisfied because the printing business generates revenue supporting literacy programs", "The operational test is likely not satisfied because devoting 35% of expenditures to an unrelated commercial business exceeds the permissible insubstantial part of non-exempt activity", "The operational test is automatically failed only if non-exempt activities exceed 50% of total expenditures"]'::jsonb, 2, 'Under Section 501(c)(3), the operational test requires that an organization be operated primarily for exempt purposes, with only an insubstantial part of activities devoted to non-exempt purposes. Devoting 35% of expenditures to an unrelated commercial printing business is more than insubstantial, likely failing the operational test. Unlike choice A, being the single largest activity is insufficient — the organization must operate primarily for exempt purposes overall, not merely have one exempt activity among several.', 'medium', 3)
;

COMMIT;
